// ===== ALL THRESHOLDS LIVE HERE. Edit, then Deploy. =====
// Every other function node reads these values with global.get('cfg').
global.set('cfg', {
    allowed_rooms: ['room1', 'room2'],

    // Stage 6 - which controller chooses the AC mode:
    //   'rules' = transparent rules below;  'dqn' = Dueling-DQN recommendation from the ML service
    //   (research algorithm B), always passed through the same safety layer (override, comfort guard,
    //   minimum hold time, stale-data hold). Lights are always rule-based.
    ac_controller: 'rules',
    dqn_comfort_guard_c: 2.0,   // occupied and hotter than comfort + 2 C -> at least COMFORT, whatever the DQN says

    // (e) Daylight dimming per room. Room 1's sensor never exceeds ~92 lux in the whole dataset, so dimming is
    // switched OFF there (null). 300 lux is the EN 12464-1 classroom task level; Room 2 reaches ~2,015 lux.
    rooms: {
        room1: { lux_dim_threshold: null },
        room2: { lux_dim_threshold: 300 },
    },

    // Occupancy hysteresis (c): become OCCUPIED at p >= on, become EMPTY only at p < off.
    // Chosen on the VALIDATION dates (results/threshold_tuning_validation.csv): the most comfort-protective pair whose
    // lighting saving stays >= 30%. 0.6/0.4 switched lights off in 22.5% of occupied validation intervals; 0.25/0.15: 13.7%.
    occupancy_on_above: 0.25,
    occupancy_off_below: 0.15,

    // Unoccupied behaviour
    light_off_after_min: 15,      // grace period before lights go OFF and AC goes to ECO
    ac_off_after_min: 30,         // (b) AC fully OFF after 30 min empty (if no arrival expected)

    // Pre-cooling (a): arrival profile from train_models.py; threshold chosen by cross-validation on training dates.
    precool_probability: 0.2,
    precool_only_if_above_comfort_c: 0.5,

    // Comfort (the recorded BMS setpoint reaches 31 C at night, so the rules use their own comfort setpoint)
    comfort_setpoint_c: 24.0,
    boost_above_comfort_c: 1.5,

    // (c) Minimum time between switching a load down (or up while empty), in DATA minutes.
    min_hold_min: 10,

    // (d) Start fresh if data time jumps backwards or by more than this (new replay / day gap).
    reset_gap_min: 60,

    // Missing-model safeguard: if the ML service sends no occupancy probability, keep the last commands; with no
    // history, use this timetable (lights ON + COMFORT inside it, OFF + ECO outside it).
    fallback_schedule: { start_hour: 8, end_hour: 20 },

    // (f) Stale telemetry: alert if no valid reading for this many REAL seconds.
    stale_after_s: 15,
    // Command delivery: alert NO_ACK if the actuator has not acknowledged within this many REAL seconds.
    ack_timeout_s: 5,

    // Energy accounting used by the dashboard savings chart (same values as savings_experiment.py)
    dim_factor: 0.5,
    eco_factor: 0.75,

    // Validation ranges: [min, max, required]
    ranges: {
        wifi_devices: [0, 500, true],
        co2_ppm: [300, 5000, true],
        sound_db: [20, 120, true],
        humidity_pct: [0, 100, true],
        temperature_c: [10, 45, true],
        illuminance_lux: [0, 10000, true],
        setpoint_c: [15, 32, true],
        outdoor_temp_c: [10, 45, false],
        lighting_kwh: [0, 5, false],
        fcu_fan_kwh: [0, 5, false],
        plug_kwh: [0, 10, false],
        chilled_water_kwh: [0, 20, false],
        occupant_presence: [0, 1, false],
        occupant_count: [0, 500, false],
        sent_at_ms: [0, 1e14, false],
    },
});
node.status({ fill: 'green', shape: 'dot', text: 'config loaded' });

